dir:





















































































  &DefaultButton;




function dir$dmbanner(p){
  this.constructor(p);
  document._dir = p;
}


function uploadImages() {
	var input = document.getElementById("fileInput");
	var files = input.files;

	var p = document._dir;

	if (files.length > 5) {
		alert("Chỉ được phép chọn tối đa 5 hình ảnh.");
		return;
	} else {
		var formData = new FormData();
		for (var i = 0; i < files.length; i++) {
			formData.append("file" + i, files[i]);
		}
	}

	for (var i = 0; i < 5; i++) {
		if (i < files.length) {
			var fileName = files[i].name;
			p.valForm('ximage' + (i + 1), "/Uploaded/" + fileName, true);
		} else {
			p.valForm('ximage' + (i + 1), "", true);
		}
	}

	var btn = document.querySelector('button.btn-primary');
	btn.addEventListener("click", function() {
		$.ajax({
			url: '/AppHandler/UploadHandler.ashx',
			type: 'POST',
			data: formData,
			processData: false,
			contentType: false,
			success: function (response) {
				alert(response); // Hiển thị thông báo thành công hoặc lỗi
			}
		});
	});
}
function updateImage(index) {
	var p = document._dir;

	var input = document.getElementById("fileUpload" + index);
	var selectedFile = input.files[0];
	if (selectedFile) {
		// Cập nhật đường dẫn ảnh trong input ẩn tương ứng
		var path = "/Uploaded/" + selectedFile.name;
		p.valForm('ximage' + index, path, true);
		alert("Cập nhật ảnh thành công!");
		console.log( p.valForm('ximage' + index))
		var formData = new FormData();
		formData.append("file", selectedFile);

		var btn = document.querySelector('button.btn-primary');
		btn.addEventListener("click", function() {
			$.ajax({
				url: '/AppHandler/UploadHandler.ashx',
				type: 'POST',
				data: formData,
				processData: false,
				contentType: false,
				success: function (response) {
					alert(response); // Hiển thị thông báo thành công hoặc lỗi
				}
			});
		});
	} else {
		alert("Chọn ảnh mới không hợp lệ.");
	}
}
function browseServer(value, src) {
	var p = document._dir;
	var finder = new CKFinder();
	finder.selectActionFunction = function (url) {
		p.valForm(value, url, true);
		document.getElementById(src).src = url;
	};
	finder.popup();
}
function setImages(id, name, p) {
	$('#' + id).attr("src", p.valForm(name));
}


dir$dmbanner.prototype = new DirEvent();
dir$dmbanner.prototype.afterInit = function(){
  var p = this._dir;
  setTimeout(function() {		
		setImages('img_ximage1', 'ximage1', p);
	}, 500);
}
